function answer(service: string, id: string, problems: string[], q: string, a: string, aq: string, aa: string, sources: Source[]): MatterSourceGuidance {
  return { region: "syr", service, id: `syr-completion-${id}`, problems, reviewedAt: "2026-09-11", en: { q, a }, ar: { q: aq, a: aa }, sources };
}

